from pathlib import Path
import datetime,gzip,json,hashlib,subprocess,sys
out=Path(__file__).resolve().parents[1];phase=sys.argv[1];b=json.load(gzip.open(out/'before.json.gz'));sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();hashes={f:sha(f) for f in b['hashes']}
if phase.startswith('before'):assert hashes==b['hashes']
cases={'relative-zero':'text(size:2em)[A] == text(size:0pt)[A]','affine-absolute-part':'text(size:2em+3pt)[A] == text(size:3pt)[A]','relative-resolved':'text(size:2em)[A] == text(size:24pt)[A]','same':'text(size:2em)[A] == text(size:2em)[A]','fill':'text(fill:red)[A] == text(fill:blue)[A]','different-body':'text(size:2em)[A] == text(size:2em)[B]','plain':'text(size:2em)[A] == [A]','strong':'strong[A] == text(weight:"bold")[A]','nested-single':'text(size:2em,text(fill:red)[A]) == text(size:24pt)[A]','nested3-single':'text(size:2em,text(fill:red,text(size:3pt)[A])) == text(size:24pt)[A]','heading-child':'heading(text(size:2em)[A]) == heading(text(size:24pt)[A])','strong-child':'strong(text(size:2em)[A]) == strong(text(size:24pt)[A])','array':'(text(size:2em)[A],)==(text(size:24pt)[A],)','dictionary':'(a:text(size:2em)[A])==(a:text(size:24pt)[A])','in':'text(size:2em)[A] in (text(size:24pt)[A],)','not-in':'text(size:2em)[A] not in (text(size:24pt)[A],)','neq':'text(size:2em)[A] != text(size:24pt)[A]','empty-style':'text([A]) == [A]','lang':'text(lang:"en")[A] == text(lang:"fr")[A]','kinds':'strong[A] == emph[A]','nan-style':'text(size:float("nan")*1pt)[A] == text(size:2em)[A]','none-body':'text(size:2em,none)==text(size:24pt,none)','nested-array':'((text(size:2em)[A],),)==((text(size:24pt)[A],),)','different-nested-body':'text(size:2em,text(fill:red)[A]) == text(size:24pt)[B]'}
bins={'tekt':Path('target/debug/typst').resolve(),'vanilla':Path('lab/typst-original/target/release/typst').resolve()};assert sha(bins['vanilla'])=='7fa91e57df43593beef70967898d776d69c8f593b1f324ccb552290821c171ea';r=dict(start=datetime.datetime.now(datetime.timezone.utc).isoformat(),head=b['head'],source_hashes=hashes,status=subprocess.check_output(['git','status','--porcelain=v1'],text=True),diffstat=subprocess.check_output(['git','diff','HEAD','--stat'],text=True),binaries={k:dict(path=str(p),sha256=sha(p)) for k,p in bins.items()},cases=[])
for name,expr in cases.items():
 for kind,bin in bins.items():
  cmd=[str(bin),'eval',expr,'--in',str(out/'empty.typ'),'--format','json'];z=subprocess.run(cmd,capture_output=True,text=True,timeout=30);r['cases'].append(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),name=name,expression=expr,binary=kind,argv=cmd,exit=z.returncode,stdout=z.stdout,stderr=z.stderr));print(name,kind,z.returncode,z.stdout.strip(),flush=True)
r.update(end=datetime.datetime.now(datetime.timezone.utc).isoformat(),sources_unchanged=all(sha(p)==h for p,h in hashes.items()));assert r['sources_unchanged']
with gzip.open(out/(phase+'-measurement.json.gz'),'wt') as f:json.dump(r,f)
